if (
  value.scope.projectId !== scope.projectId ||
  value.scope.organizationId !== scope.organizationId
) {
  return err(repositoryUnavailable(`${operation}:${CHANNELS_SCOPE_FORGED}`));
}
return ok(value);

const already = await load(link.owner, link.channelThreadKey);
if (already !== null) {
  return err(
    threadLinkConflict(link.channelThreadKey, already.threadId, link.threadId),
  );
}

if (ancestry.projectId === null || ancestry.organizationId === null) {
  return unreadable<ReturnType<typeof environmentScope>>(UNRESOLVED_SCOPE_ANCESTRY, where);
}

if (!(CHANNEL_EVENT_STATUSES as readonly string[]).includes(row.status)) {
  return unreadable(UNREADABLE_EVENT_STATUS, `ChannelEventInbox/${row.id}:${row.status}`);
}

if (state === "REFRESHING") {
  if (claimId === null || startedAt === null) {
    return refuse(operation, REFRESH_FENCE_INCOHERENT, "REFRESHING without a claim");
  }
  return requireUuid(operation, "tokenRefreshClaimId", claimId);
}

return leaseOwner === null && leaseExpiresAt === null
  ? null
  : refuse(operation, EVENT_LEASE_INCOHERENT, `${status} holding a lease`);

for (const check of checks) {
  if (check !== null) return check;
}

return Number.isInteger(value) && value >= 0
  ? null
  : refuse(operation, GENERATION_NEGATIVE, `${field}=${String(value)}`);

if (value.length > MAX_AGENT_ROUTING_RULES) {
  return refuse(operation, ROUTING_TOO_MANY_RULES, String(value.length));
}
